describe("nearbyCellsFor — hazard cell streaming (TASK-48 client discs)", () => {
  /** Register a cell on a shard at `pos` with `radius`. */
  function place(
    shard: Shard,
    hazardId: string,
    pos: { x: number; y: number; z: number },
    radius: number,
    kind: "storm" | "radzone" | "drones" = "storm",
