    shard.hazardCells.set(
      hazardId,
      makeCell({
        hazardId,
        planetId: "p1",
        kind,
        pos,
        radius,
        intensity: kind === "radzone" ? HAZARD_RADZONE_DAMAGE_PER_S : HAZARD_STORM_DAMAGE_PER_S,
        droneCount: 0,
        droneIdPrefix: `drone:${hazardId}`,
      }),
    );
  }

